import numpy as np

def r(x):
    # Monotonicity: decreasing grid spacing x (h) increases the accuracy.
    # Since the FDM solution systematically underestimates the exact solution,
    # a smaller h increases the ratio towards 1.0.
    return 0.2 * x

def R(y_orig, y_new):
